ACTUAL_SHA="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL_SHA" == "$EXPECTED_ZIP_SHA256" ]] || { echo "ZIP SHA 불일치" >&2; exit 1; }
echo "ZIP_SHA256=OK $ACTUAL_SHA"
unzip -q "$TMP/$ZIP_NAME" -d "$TMP/src"
ROOT="$TMP/src/$ROOT_NAME"
[[ -d "$ROOT" ]] || { echo "ZIP root 없음: $ROOT_NAME" >&2; exit 1; }
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null) || { echo "SOURCE_MANIFEST 불일치" >&2; exit 1; }
echo "SOURCE_MANIFEST=PASS"

say "3/7 공식 계약/회귀 정적검증 (selfcheck는 Docker 의존성 설치 후 실행)"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/evidence_engine.py" "$ROOT/app/archive_engine.py" "$ROOT/app/shadow_engine.py" "$ROOT/app/rs_shadow_engine.py" "$ROOT/scripts/replay_backtest.py"
node --check "$ROOT/static/nova.js" >/dev/null
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null)
python3 - "$ROOT" <<'PYDEPGUARD'
from pathlib import Path
import sys
r=Path(sys.argv[1])
d=(r/'Dockerfile').read_text(encoding='utf-8')
req=(r/'requirements.txt').read_text(encoding='utf-8')
assert 'httpx==0.28.1' in req, 'requirements.txt: httpx pin missing'
assert 'websockets==15.0.1' in req, 'requirements.txt: websockets pin missing'
pip_marker='RUN pip install --no-cache-dir -r requirements.txt'
self_marker='python scripts/selfcheck.py'
assert pip_marker in d, 'Dockerfile: requirements install missing'
assert self_marker in d, 'Dockerfile: selfcheck missing'
assert d.index(pip_marker) < d.index(self_marker), 'Dockerfile: selfcheck runs before dependencies'
print('DEPENDENCY_ORDER=PASS selfcheck_after_pip_install')
main=(r/'app/main.py').read_text(encoding='utf-8')
assert 'WS_REG_ITEM_BUDGET' in main and 'SESSION_AWARE_HARD_CAP' in main, 'WS budget guard missing'
assert 'STABLE_LIVE_BOARD_WS_ADMISSION_HYSTERESIS' in main and 'def stable_live_board' in main, 'stable live board guard missing'
assert 'normalized_session_vwap' in main and 'session_vwap_source' in main, 'session VWAP normalization missing'
assert 'LIVE_BOARD_MIN_HOLD_SECONDS' in main and 'LIVE_BOARD_STALE_GRACE_SECONDS' in main, 'live board hysteresis constants missing'
assert 'def _prebuy_recommendation_row' in main and 'PRE_SURGE_BUY_RECOMMENDATION' in main, 'pre-surge BUY recommendation missing'
assert "@app.get('/api/prebuy-recommendations')" in main, 'dedicated prebuy API missing'
html=(r/'static/index.html').read_text(encoding='utf-8'); js=(r/'static/nova.js').read_text(encoding='utf-8')
assert 'id="preBuyCards"' in html and 'id="preBuyRows"' not in html, 'primary BUY card container missing'
assert "fetch('/api/prebuy-recommendations'" in js and 'function prebuyCard(' in js, 'primary BUY renderer bridge missing'
assert 'def _close_preview_rows' in main and 'PREVIEW' in main, 'close/smart preview pipeline missing'
assert 'WS_ACTIVE_RECONNECT_MAX' in main and 'WS_STALE_NO_MESSAGE_RECONNECT' in main, 'active WS self-heal missing'
assert "state='RECONNECTING'" in main and 'live_board_reconnecting' in main, 'reconnect display-hold missing'
assert "nxt_target=trade_codes if prof['nxt'] else frozenset()" in main, 'active-venue NXT target guard missing'
print('WS_BUDGET_STABLE_BOARD_VWAP_GUARD=PASS')
print('HOST_SELFCHECK=SKIPPED_BY_DESIGN')
PYDEPGUARD
python3 - "$ROOT" <<'PYVERIFY'
import json,sys
from pathlib import Path
r=Path(sys.argv[1]); m=(r/'app/main.py').read_text(encoding='utf-8'); b=json.loads((r/'BUILD_INFO.json').read_text(encoding='utf-8'))
checks = [
    ('APP_VERSION', "APP_VERSION='NOVA-2.4.22'" in m),
    ('WS_TYPES_0B_0u_0D', "'trade_type':'0B','program_type':'0u','orderbook_type':'0D'" in m),
    ('WS_TRADE_NOT_0A', "'trade_type':'0A'" not in m and "'trade':'0A'" not in m),
    ('PROGRAM_API_KA90003_ONLY', 'ka90003' in m and 'ka90004' not in m),
    ('VENUE_TRUTH_FUNCTION', 'def venue_from_realtime_item' in m),
    ('PROGRAM_SOURCE_0u', "source='0u'" in m),
    ('ORDERBOOK_FID_RANGES', "range(41,51)" in m and "range(61,71)" in m),
    ('ORDERBOOK_FULL_DEPTH_0D', "'orderbook_type':'0D'" in m and '0C=stock best quote' in b.get('orderbook_contract_audit','')),
    ('STABLE_LIVE_BOARD', 'STABLE_LIVE_BOARD_WS_ADMISSION_HYSTERESIS' in m and 'stable_live_board' in m),
    ('UNIT_SAFE_SESSION_VWAP', 'normalized_session_vwap' in m and 'session_vwap_policy' in b),
    ('BUILD_VERSION', b.get('version')=='NOVA-2.4.22'),
    ('BUILD_LIVE_CONTRACT', '0B/0u/0D' in b.get('live_contract','')),
    ('BUILD_KRX_BACKFILL', 'ka90003' in b.get('krx_close_backfill','')),
    ('BUY_POLICY_FROZEN', 'FROZEN_FROM_2.4.8' in b.get('buy_policy','')),
    ('NXT_DISPLAY_POLICY', 'DISPLAY_ONLY_CONSERVATIVE' in b.get('nxt_signal_management','')),
    ('ALERT_TOGGLE_POLICY', 'USER_CONTROLLED_V2' in b.get('alert_toggle','')),
    ('RS_LEADER_TABLE', b.get('rs_leader_table','').startswith('V2 TOP10 display-only')),
    ('PRE_SURGE_BUY_PRIMARY', 'def _prebuy_recommendation_row' in m and 'PRE_SURGE_BUY_RECOMMENDATION' in m),
    ('CLOSE_PREVIEW', 'def _close_preview_rows' in m and '19:30 공식선정 전 실시간 PREVIEW' in m),
    ('BUILD_PREBUY', (lambda x: all(tok in x for tok in ('primary','pre-surge','buy_early','buy_ready')))(b.get('buy_recommendation','').lower())),
    ('WS_SELF_HEAL', 'ACTIVE_FAST_RECONNECT_MAX3S' in b.get('ws_registry','') and 'NO_MESSAGE_WATCHDOG' in b.get('ws_registry','')),
    ('RECONNECT_BOARD_HOLD', 'active reconnect retains last board' in b.get('ui_live_board','')),
    ('R12_PRIMARY_RENDER', "@app.get('/api/prebuy-recommendations')" in m),
]
failed=[name for name,ok in checks if not ok]
for name,ok in checks:
    print(f'STATIC_CHECK {name}={"PASS" if ok else "FAIL"}')
if failed:
    raise SystemExit('STATIC_CONTRACT_FAILED: ' + ','.join(failed))
assert 'PREBUY_MIN_HOLD_SECONDS' in m and 'def _raw_prebuy_recommendations' in m and 'display_status' in m
html=(r/'static/index.html').read_text(encoding='utf-8'); js=(r/'static/nova.js').read_text(encoding='utf-8')
assert 'id="preBuyCards"' in html and "fetch('/api/prebuy-recommendations'" in js and 'setInterval(loadPrimaryBuy,2500)' in js
print('R12_PRIMARY_BUY_RENDER_BRIDGE_STATIC=PASS')
assert b.get('ui_priority','').startswith('PRE-SURGE BUY TOP10')
print('PRIMARY_BUY_STABLE_STATIC=PASS')
print('OFFICIAL_CONTRACT_STATIC=PASS 0B/0u/0D + ka90003')
print('LIVE_POLICY_PARITY=PASS BUY/RECOVERY/EXIT thresholds unchanged')
PYVERIFY

